// ======= ENHANCED PERFORMANCE OPTIMIZATIONS WITH TAGS SUPPORT =======
const DOM = {
	contentArea: null,
	mobileMenu: null,
	toast: null,
	toastMessage: null,
	toastBox: null,
	imageModal: null,
	modalImage: null,
	init() {
		this.contentArea = document.getElementById("content-area")
		this.mobileMenu = document.getElementById("mobile-menu")
		this.toast = document.getElementById("toast")
		this.toastMessage = document.getElementById("toast-message")
		this.toastBox = this.toast?.querySelector(".toast-box")
		this.imageModal = document.getElementById("image-modal")
		this.modalImage = document.getElementById("modal-image")
	},
}

const debounce = (func, wait) => {
	let timeout
	return function executedFunction(...args) {
		const later = () => {
			clearTimeout(timeout)
			func(...args)
		}
		clearTimeout(timeout)
		timeout = setTimeout(later, wait)
	}
}

// ======= THEME SYSTEM =======
let currentTheme = localStorage.getItem("theme") || "default"

function initThemeSystem() {
	document.documentElement.setAttribute("data-theme", currentTheme)
	updateThemeUI()

	// Setup theme dropdown click outside handler
	document.addEventListener("click", (e) => {
		const themeDropdown = document.getElementById("theme-dropdown")
		const themeSwitcher = document.querySelector(".theme-switcher")

		if (themeDropdown && themeSwitcher) {
			if (!themeSwitcher.contains(e.target)) {
				themeDropdown.classList.remove("active")
			}
		}
	})
}

function toggleThemeDropdown() {
	const dropdown = document.getElementById("theme-dropdown")
	if (dropdown) {
		dropdown.classList.toggle("active")
	}
}

function setTheme(theme) {
	currentTheme = theme
	document.documentElement.setAttribute("data-theme", theme)
	localStorage.setItem("theme", theme)
	updateThemeUI()
	toggleThemeDropdown()
}

function updateThemeUI() {
	document.querySelectorAll(".theme-option").forEach((option) => {
		option.classList.remove("active")
		if (option.dataset.theme === currentTheme) {
			option.classList.add("active")
		}
	})
}

// ======= UTILITY FUNCTIONS =======
let toastTimeout

function showToast(message, type = "success") {
	const toast = document.getElementById("toast")
	const toastBox = toast?.querySelector(".toast-box")
	const toastMessage = document.getElementById("toast-message")

	if (!toast || !toastBox || !toastMessage) {
		console.log("Toast elements not found")
		return
	}

	if (toastTimeout) {
		clearTimeout(toastTimeout)
	}

	toastMessage.textContent = message
	toast.classList.remove("hidden")
	toastBox.classList.remove("hide")
	toastBox.classList.add("show")

	toastTimeout = setTimeout(() => {
		toastBox.classList.remove("show")
		toastBox.classList.add("hide")
		setTimeout(() => {
			toast.classList.add("hidden")
		}, 500)
	}, 2500)
}

const copyToClipboard = async (text, message) => {
	try {
		await navigator.clipboard.writeText(text)
		showToast(message)
	} catch (err) {
		console.error("Failed to copy:", err)
		const textArea = document.createElement("textarea")
		textArea.value = text
		textArea.style.position = "fixed"
		textArea.style.left = "-999999px"
		textArea.style.top = "-999999px"
		document.body.appendChild(textArea)
		textArea.focus()
		textArea.select()
		try {
			document.execCommand("copy")
			showToast(message)
		} catch (fallbackErr) {
			showToast("Copy failed - please copy manually", "error")
		}
		document.body.removeChild(textArea)
	}
}

function copyPassword(pass) {
	copyToClipboard(pass, "Password copied to clipboard!")
}

function copyDiscordInvite() {
	copyToClipboard("https://discord.gg/BBX8vfN4gQ", "Discord invite link copied!")
}

function toggleDiscordInvite() {
	const wrapper = document.getElementById("discord-invite-wrapper")
	wrapper?.classList.toggle("open")
}

// FIXED: Enhanced modal functions with proper z-index management
function openModal(src) {
	const modal = document.getElementById("image-modal")
	const modalImage = document.getElementById("modal-image")

	if (!modal || !modalImage) return

	modalImage.src = src
	modal.classList.remove("hidden")
	document.body.style.overflow = "hidden"

	// FIXED: Hide floating navigation and other overlapping elements
	hideElementsForModal(true)
}

function closeModal() {
	const modal = document.getElementById("image-modal")
	if (!modal) return

	modal.classList.add("hidden")
	document.body.style.overflow = "auto"

	// FIXED: Show floating navigation and other elements again
	hideElementsForModal(false)
}

// FIXED: New function to manage element visibility during modal
function hideElementsForModal(hide) {
	const elementsToHide = [".floating-nav-modern", ".mobile-nav-toggle", ".premium-navbar", ".toast-container"]

	elementsToHide.forEach((selector) => {
		const element = document.querySelector(selector)
		if (element) {
			if (hide) {
				element.style.display = "none"
			} else {
				element.style.display = ""
			}
		}
	})
}

function toggleDropdown() {
	const dropdown = document.querySelector(".dropdown")
	if (!dropdown) return

	const icon = dropdown.querySelector(".dropbtn i")
	const isActive = dropdown.classList.toggle("active")

	if (icon) {
		icon.style.transform = isActive ? "rotate(180deg)" : "rotate(0deg)"
	}
}

function animateContent() {
	const contentArea = document.getElementById("content-area")
	contentArea?.classList.remove("opacity-0")
}

function closeMobileMenu() {
	const mobileMenu = document.getElementById("mobile-menu")
	if (mobileMenu) {
		mobileMenu.classList.add("hidden")
	}
}

