// ======= INITIALIZATION =======
function initializeApp() {
	// Initialize base DOM and theme systems
	DOM.init()
	initThemeSystem()

	// Toggle mobile menu
	const mobileMenuButton = document.getElementById("mobile-menu-button")
	const mobileMenu = document.getElementById("mobile-menu")
	if (mobileMenuButton && mobileMenu) {
		mobileMenuButton.addEventListener("click", () => {
			mobileMenu.classList.toggle("hidden")
		})
	}

	// Close image modal on background click
	const imageModal = document.getElementById("image-modal")
	if (imageModal) {
		imageModal.addEventListener("click", (e) => {
			if (e.target === e.currentTarget) {
				closeModal()
			}
		})
	}

	// Close modal on Escape key press
	document.addEventListener("keydown", (e) => {
		if (e.key === "Escape") {
			closeModal()
		}
	})

	// Setup dropdown toggle for each link in dropdown-content
	document.querySelectorAll(".dropdown-content a").forEach((link) => link.addEventListener("click", toggleDropdown))

	// Setup intersection observer for fade-in image effect
	const observer = new IntersectionObserver(
		(entries, obs) => {
			entries.forEach((entry) => {
				if (entry.isIntersecting) {
					entry.target.classList.add("opacity-100", "translate-y-0")
					obs.unobserve(entry.target)
				}
			})
		}, {
			threshold: 0.1,
			rootMargin: "50px",
		},
	)

	document.querySelectorAll(".fade-img").forEach((img) => observer.observe(img))

	// Load saved page or default content
	const savedPage = localStorage.getItem("currentPage")
	if (savedPage === "assets") {
		loadAllAssets()
	} else if (savedPage) {
		loadContent(savedPage)
	} else {
		renderWelcomeContent()
	}
}

if (document.readyState === "loading") {
	document.addEventListener("DOMContentLoaded", initializeApp)
} else {
	initializeApp()
}

// Cache DOM elements to improve performance
const contactModal = document.getElementById("contactModal")
const closeContactButton = document.getElementById("closeContactModal")

// Function to open the contact modal
function openContactModal() {
	contactModal.style.display = "block"
}

// Event listener to close modal when close button is clicked
closeContactButton.addEventListener("click", () => {
	contactModal.style.display = "none"
})

// Close modal when user clicks outside of it
window.addEventListener("click", (event) => {
	if (event.target === contactModal) {
		contactModal.style.display = "none"
	}
})

function openContactModalAfterMenuClose() {
	closeMobileMenu()
	setTimeout(openContactModal, 150)
}

function closeContactModal() {
	document.getElementById("contactModal").style.display = "none"
}

function toggleMobileMenu() {
	const menu = document.getElementById("mobile-menu")
	const [navMenu, overlay] = menu.querySelectorAll(".mobile-nav-menu, .mobile-nav-overlay")
	const isOpen = navMenu.classList.contains("active")

	if (isOpen) {
		// Închidere animată
		navMenu.classList.remove("active")
		overlay.classList.remove("active")
		menu.classList.add("hidden")
	} else {
		// Deschidere animată
		menu.classList.remove("hidden")
		requestAnimationFrame(() => {
			navMenu.classList.add("active")
			overlay.classList.add("active")
		})
	}
}